// Keep only nudges that are due right now:
//   status  = 'approved'  (human-reviewed via the review page / Workflow E)
//   scheduled_date <= today (catches overdue rows too)
//   if same day: scheduled_time <= current time
// Nudges still 'needs_review' or 'rejected' are intentionally never sent.

const today       = $now.toISODate();            // 'YYYY-MM-DD'
const currentTime = $now.toFormat('HH:mm');      // 'HH:MM'

const due = items.filter(item => {
  const { status, scheduled_date, scheduled_time } = item.json;
  if (status !== 'approved') return false;
  if (scheduled_date > today) return false;
  if (scheduled_date === today && scheduled_time > currentTime) return false;
  return true;
});

// Returning an empty array skips all downstream nodes cleanly.
return due;

// Build the Meta WhatsApp Cloud API request body for each due nudge.
//
// Template routing:
//   hello_world          — dev/test, no parameters, no Meta approval needed
//   health_plan_reminder — production; message_body injected into {{1}}
//
// recipient_phone must be E.164, e.g. +61412345678.
// schedule_id is deterministic (idempotent across retries).
//
// Step 7 (build order): insert streak-check logic HERE to pick standard
// vs reflective variant before building the payload.

return items.map(item => {
  const {
    recipient_phone,
    message_body,
    template_name,
    nudge_id,
    user_id
  } = item.json;

  let template;
  if (template_name === 'hello_world') {
    template = {
      name: 'hello_world',
      language: { code: 'en_US' }
    };
  } else {
    // health_plan_reminder body:
    // "Reminder from your health plan: {{1}}. Reply DONE when completed, or SKIP to skip today."
    template = {
      name: 'health_plan_reminder',
      language: { code: 'en_US' },
      components: [{
        type: 'body',
        parameters: [{ type: 'text', text: message_body }]
      }]
    };
  }

  item.json.whatsapp_payload = JSON.stringify({
    messaging_product: 'whatsapp',
    to: recipient_phone,
    type: 'template',
    template
  });

  // Deterministic — safe to re-run if a prior execution partially failed.
  item.json.schedule_id = 'sch_' + nudge_id;

  return item;
});

// The HTTP Request node replaces item data with the API response body.
// This node merges the original nudge data back in and extracts wa_message_id.
//
// Meta API response shape:
//   { messaging_product, contacts: [...], messages: [{ id: 'wamid.HBgN...' }] }
//
// wa_message_id is stored in schedule_state so Workflow C can correlate
// a SKIP follow-up reply (which carries context.id) back to its nudge_id.

const nudges = $('Build WhatsApp Payload').all();

return items.map((responseItem, i) => {
  const nudge    = nudges[i] ? nudges[i].json : {};
  const response = responseItem.json;

  const wa_message_id = (response.messages && response.messages[0])
    ? response.messages[0].id
    : null;

  return {
    json: {
      ...nudge,
      wa_message_id
    }
  };
});
